import { NodeServices } from "@effect/platform-node";
import { describe, expect, it } from "@effect/vitest";
import { Effect, FileSystem, Path } from "effect";
import { analyzeSources } from "../src/deep-analysis/analyze.ts";
import { parseLsTree, sourceFiles } from "../src/deep-analysis/tree.ts";

const files: Record<string, string> = {
  "src/app.ts": `import { Effect } from "effect";\nexport const main = Effect.gen(function* () {});\n`,
  "src/plain.ts": `export const x = 1;\n`,
  "src/client.ts": `// Code generated by openapi-typescript. DO NOT EDIT.\nimport { Schema } from "effect";\nexport const A = Schema.String;\n`,
  "src/routeTree.gen.ts": `export const routes = [];\n`,
  "test/app.test.ts": `import { Effect } from "effect";\nEffect.runPromise(Effect.void);\n`,
};

describe("analyzeSources", () => {
  it.effect("moves header-detected generated files into the generated role", () =>
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem;
      const path = yield* Path.Path;
      const dir = yield* fs.makeTempDirectoryScoped({ prefix: "e20r-analyze-" });
      for (const [file, text] of Object.entries(files)) {
        yield* fs.makeDirectory(path.join(dir, path.dirname(file)), { recursive: true });
        yield* fs.writeFileString(path.join(dir, file), text);
      }
      const tree = parseLsTree(
        Object.keys(files)
          .map((file) => `100644 blob aaaa\t${file}\0`)
          .join(""),
      );
      const entries = sourceFiles(tree, new Set());

      const analysis = yield* analyzeSources(dir, entries, { maxParseBytes: 1_000_000 });

      const byRole = Object.fromEntries(
        analysis.totals.map((row) => [row.role, [row.files, row.effectFiles]]),
      );
      expect(byRole).toEqual({ source: [2, 1], generated: [2, 1], test: [1, 1] });
      expect(analysis.effectFiles.map((row) => [row.file, row.role])).toEqual([
        ["src/app.ts", "source"],
        ["src/client.ts", "generated"],
        ["test/app.test.ts", "test"],
      ]);
    }).pipe(Effect.scoped, Effect.provide(NodeServices.layer)),
  );
});
